-- YZ talimat taslaklarının uzman düzeltmesi (12.11.2026) — 9 tip, 21 madde
-- Kütüphane kaydı + firmalara eklenmiş ve henüz düzenlenmemiş (açıklaması 'Yapay zekâ…' olan) kopyalar güncellenir.

USE `u2858154_mehse`;

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, araç kaldırma liftinin 6331 sayılı İSG Kanunu, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği ve TS EN 1493 standardına uygun olarak güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Sıvı sıçramalarına ve parçacıklara karşı koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Baş yaralanmaları riskine karşı koruyucu baret (TS EN 397) kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma liftinin yıllık periyodik kontrol etiketinin güncel olduğu kontrol edilmelidir.\",\"Lift kollarındaki kauçuk kaldırma pabuçlarının yıpranmadığı ve sağlam olduğu doğrulanmalıdır.\",\"Mekanik güvenlik kilitleri, hidrolik hortumlar ve pabuç sabitleme pimleri gözle kontrol edilmelidir.\",\"Acil stop butonunun ve sesli ikaz sisteminin çalışırlığı test edilmelidir.\",\"Lift etrafındaki çalışma sahası yağ, gres ve takılmaya sebep olacak malzemelerden temizlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç, lift kollarının tam ortasına gelecek şekilde konumlandırılmalı ve kaldırma noktaları üretici talimatlarına göre ayarlanmalıdır.\",\"Araç tekerlekleri yerden 10-15 cm kaldırıldıktan sonra durdurulmalı ve aracın dengede olduğu sallanma testi ile doğrulanmalıdır.\",\"Araç istenen yüksekliğe kaldırıldıktan sonra mekanik emniyet kilitleri (stoperler) mutlaka devreye sokulmalıdır.\",\"Lift kilitlenmeden ve mekanik güvenlik tam sağlanmadan araç altında kesinlikle çalışılmamalıdır.\",\"Liftin azami taşıma kapasitesi (tonajı) hiçbir koşulda aşılmamalıdır.\",\"Kaldırma ve indirme işlemleri esnasında hareketli aksamların yakınında durulmamalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında araç emniyetli bir şekilde zemin seviyesine indirilmeli ve lift kolları serbest konuma getirilmelidir.\",\"Lift panosundaki ana şalter kapatılmalı ve sistem enerjisi kesilmelidir.\",\"Bakım, onarım ve temizlik işlemleri öncesinde etiketleme ve kilitleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Taşıyıcı kollar ve zemin hidrolik yağ ve kirden temizlenmelidir.\",\"Hidrolik yağ seviyesi ve kaçak durumu periyodik olarak kontrol edilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç lift üzerindeyken içinde insan veya canlı bulunması kesinlikle yasaktır.\",\"Mekanik emniyet kilitleri arızalı veya devre dışı bırakılmış liftlerin kullanılması yasaktır.\",\"Lift hareketi esnasında araca müdahale edilmesi veya aracın üzerine çıkılması yasaktır.\",\"Yetkisiz ve eğitimi bulunmayan personelin lift kumanda panosunu kullanması yasaktır.\",\"Araç lift üzerindeyken aracın ağırlık merkezini ciddi şekilde değiştirecek ağır parça sökümlerinin desteksiz yapılması yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, sarsıntı veya hidrolik sızıntı tespit edildiğinde işlem derhal durdurulmalıdır.\",\"Acil bir durumda derhal acil stop butonuna basılmalı ve ana güç kaynağı kesilmelidir.\",\"Elektrik kesintisi veya arıza durumunda askıda kalan araç için yetkisiz kişilerce manuel indirme müdahalesi yapılmamalıdır.\",\"Tüm arıza ve güvensiz durumlar derhal İSG uzmanına ve teknik bakım sorumlusuna bildirilmelidir.\",\"Arızalı lift üzerine \'ARIZALIDIR - KULLANMAYINIZ\' uyarısı asılmalı ve kilitlenmelidir.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Araç Kaldırma Lifti';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, araç kaldırma liftinin 6331 sayılı İSG Kanunu, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği ve TS EN 1493 standardına uygun olarak güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Sıvı sıçramalarına ve parçacıklara karşı koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Baş yaralanmaları riskine karşı koruyucu baret (TS EN 397) kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma liftinin yıllık periyodik kontrol etiketinin güncel olduğu kontrol edilmelidir.\",\"Lift kollarındaki kauçuk kaldırma pabuçlarının yıpranmadığı ve sağlam olduğu doğrulanmalıdır.\",\"Mekanik güvenlik kilitleri, hidrolik hortumlar ve pabuç sabitleme pimleri gözle kontrol edilmelidir.\",\"Acil stop butonunun ve sesli ikaz sisteminin çalışırlığı test edilmelidir.\",\"Lift etrafındaki çalışma sahası yağ, gres ve takılmaya sebep olacak malzemelerden temizlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç, lift kollarının tam ortasına gelecek şekilde konumlandırılmalı ve kaldırma noktaları üretici talimatlarına göre ayarlanmalıdır.\",\"Araç tekerlekleri yerden 10-15 cm kaldırıldıktan sonra durdurulmalı ve aracın dengede olduğu sallanma testi ile doğrulanmalıdır.\",\"Araç istenen yüksekliğe kaldırıldıktan sonra mekanik emniyet kilitleri (stoperler) mutlaka devreye sokulmalıdır.\",\"Lift kilitlenmeden ve mekanik güvenlik tam sağlanmadan araç altında kesinlikle çalışılmamalıdır.\",\"Liftin azami taşıma kapasitesi (tonajı) hiçbir koşulda aşılmamalıdır.\",\"Kaldırma ve indirme işlemleri esnasında hareketli aksamların yakınında durulmamalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma tamamlandığında araç emniyetli bir şekilde zemin seviyesine indirilmeli ve lift kolları serbest konuma getirilmelidir.\",\"Lift panosundaki ana şalter kapatılmalı ve sistem enerjisi kesilmelidir.\",\"Bakım, onarım ve temizlik işlemleri öncesinde etiketleme ve kilitleme (EKED\\/LOTO) prosedürü uygulanmalıdır.\",\"Taşıyıcı kollar ve zemin hidrolik yağ ve kirden temizlenmelidir.\",\"Hidrolik yağ seviyesi ve kaçak durumu periyodik olarak kontrol edilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Araç lift üzerindeyken içinde insan veya canlı bulunması kesinlikle yasaktır.\",\"Mekanik emniyet kilitleri arızalı veya devre dışı bırakılmış liftlerin kullanılması yasaktır.\",\"Lift hareketi esnasında araca müdahale edilmesi veya aracın üzerine çıkılması yasaktır.\",\"Yetkisiz ve eğitimi bulunmayan personelin lift kumanda panosunu kullanması yasaktır.\",\"Araç lift üzerindeyken aracın ağırlık merkezini ciddi şekilde değiştirecek ağır parça sökümlerinin desteksiz yapılması yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Çalışma sırasında anormal ses, sarsıntı veya hidrolik sızıntı tespit edildiğinde işlem derhal durdurulmalıdır.\",\"Acil bir durumda derhal acil stop butonuna basılmalı ve ana güç kaynağı kesilmelidir.\",\"Elektrik kesintisi veya arıza durumunda askıda kalan araç için yetkisiz kişilerce manuel indirme müdahalesi yapılmamalıdır.\",\"Tüm arıza ve güvensiz durumlar derhal İSG uzmanına ve teknik bakım sorumlusuna bildirilmelidir.\",\"Arızalı lift üzerine \'ARIZALIDIR - KULLANMAYINIZ\' uyarısı asılmalı ve kilitlenmelidir.\"]}]', `updated_at` = NOW() WHERE `baslik` = 'ARAÇ KALDIRMA LİFTİ GÜVENLİ ÇALIŞMA TALİMATI' AND `aciklama` LIKE 'Yapay zek%';

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, bina ve tesislerde kullanılan insan ve yük asansörlerinin güvenli kullanımını, periyodik kontrollerini ve bakım-onarım süreçlerinde alınacak iş sağlığı ve güvenliği tedbirlerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"TS EN 397 standardına uygun çene bantlı endüstriyel emniyet bareti kullanılmalıdır.\",\"TS EN ISO 20345 standardına uygun S3 çelik burunlu ve kaymaz tabanlı iş ayakkabısı giyilmelidir.\",\"TS EN 388 standardına uygun mekanik risklere karşı koruyucu eldiven takılmalıdır.\",\"Kuyu içi ve kabin üstü çalışmalarında TS EN 361 standardına uygun tam vücut emniyet kemeri kullanılmalıdır.\",\"Bakım ve denetim esnasında TS EN 166 standardına uygun emniyet gözlüğü takılmalıdır.\",\"Gürültülü alanlardaki bakımlarda TS EN 352-2 standardına uygun kulak tıkacı veya kulaklık kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün periyodik kontrol etiketinin (yeşil etiket) geçerliliği kontrol edilmelidir.\",\"Kabin içi aydınlatma ve acil durum aydınlatma sistemlerinin çalışırlığı test edilmelidir.\",\"Kabin içi acil haberleşme butonu ve alarm sisteminin aktif olduğu doğrulanmalıdır.\",\"Kat kapılarının mekanik ve kilit sistemleri ile fotosellerin çalışması denetlenmelidir.\",\"Asansör taşıma kapasitesi (kg ve kişi sayısı) bilgilendirme levhasının yerinde olduğu kontrol edilmelidir.\",\"Kabin tabanı ile kat seviyesi hizalamasının doğru yapıldığı doğrulanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün etiketinde belirtilen azami yük ve kişi sayısı kapasitesi kesinlikle aşılmamalıdır.\",\"Yük asansörlerinde malzeme kabin merkezine dengeli yüklenmeli ve devrilmeye karşı sabitlenmelidir.\",\"Otomatik kapıların kapanması el, ayak veya malzeme ile engellenmemelidir.\",\"Kabin hareket halindeyken zıplama veya kabin dengesini bozacak hareketlerden kaçınılmalıdır.\",\"Yük yükleme ve boşaltma esnasında kabin ile kat eşiği arasındaki boşluğa dikkat edilmelidir.\",\"Kabin içi acil stop butonu yalnızca tehlike ve acil durum anında kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Bakım ve onarım işlemleri yalnızca yetkili ve sertifikalı asansör bakım servisi tarafından yürütülmelidir.\",\"Bakım öncesinde EKED (Etiketleme-Kilitleme-Emniyete Alma-Denetleme) prosedürü uygulanarak ana güç kesilmelidir.\",\"Kuyu içi veya kabin üstü çalışmasında asansör kumandası REVİZYON moduna alınmalıdır.\",\"Tüm kat kapılarına \'BAKIM VAR - KULLANMAYINIZ\' uyarı levhaları ve emniyet şeritleri asılmalıdır.\",\"Bakım bitiminde tüm koruyucu kapaklar ve güvenlik devreleri tekrar aktif hale getirilmelidir.\",\"Makine dairesi ve kuyu dibi temizlenerek giriş kapıları kilitli tutulmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kırmızı etiketli (kullanımı tehlikeli) asansörlerin işletime alınması ve kullanılması kesinlikle yasaktır.\",\"Yangın, deprem ve afet anlarında asansörlerin tahliye amacıyla kullanılması yasaktır.\",\"İnsan asansörleriyle ağır ve dengesiz yük, yük asansörleriyle yetkisiz yolcu taşınması yasaktır.\",\"Asansör kuyu dibinde veya makine dairesinde atık ve malzeme depolanması yasaktır.\",\"Kat kapısı kilit mekanizmalarına dışarıdan yetkisiz müdahale yapılması yasaktır.\",\"Asansör kabini kat seviyesinde değilken kapı zorlanarak açılmaya çalışılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kabinde mahsur kalma durumunda sakin kalınmalı ve acil durum haberleşme butonuna basılarak yardım istenmelidir.\",\"Mahsur kalan kişileri kurtarma müdahalesi sadece eğitimli yetkili personel veya itfaiye tarafından yapılmalıdır.\",\"Yetkisiz kişilerin kapı kilit anahtarı kullanarak kurtarma yapmaya çalışması engellenmelidir.\",\"Anormal ses, sarsıntı veya durma hatası algılandığında asansör derhal durdurulup yetkililere haber verilmelidir.\",\"Arızalanan asansörün ana şalteri kapatılmalı ve üzerine arıza bilgi levhası asılmalıdır.\",\"Meydana gelen tüm arıza, kaza ve ramak kala olaylar derhal İSG birimine ve bina yönetimine bildirilmelidir.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Asansör (İnsan / Yük)';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, bina ve tesislerde kullanılan insan ve yük asansörlerinin güvenli kullanımını, periyodik kontrollerini ve bakım-onarım süreçlerinde alınacak iş sağlığı ve güvenliği tedbirlerini kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"TS EN 397 standardına uygun çene bantlı endüstriyel emniyet bareti kullanılmalıdır.\",\"TS EN ISO 20345 standardına uygun S3 çelik burunlu ve kaymaz tabanlı iş ayakkabısı giyilmelidir.\",\"TS EN 388 standardına uygun mekanik risklere karşı koruyucu eldiven takılmalıdır.\",\"Kuyu içi ve kabin üstü çalışmalarında TS EN 361 standardına uygun tam vücut emniyet kemeri kullanılmalıdır.\",\"Bakım ve denetim esnasında TS EN 166 standardına uygun emniyet gözlüğü takılmalıdır.\",\"Gürültülü alanlardaki bakımlarda TS EN 352-2 standardına uygun kulak tıkacı veya kulaklık kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün periyodik kontrol etiketinin (yeşil etiket) geçerliliği kontrol edilmelidir.\",\"Kabin içi aydınlatma ve acil durum aydınlatma sistemlerinin çalışırlığı test edilmelidir.\",\"Kabin içi acil haberleşme butonu ve alarm sisteminin aktif olduğu doğrulanmalıdır.\",\"Kat kapılarının mekanik ve kilit sistemleri ile fotosellerin çalışması denetlenmelidir.\",\"Asansör taşıma kapasitesi (kg ve kişi sayısı) bilgilendirme levhasının yerinde olduğu kontrol edilmelidir.\",\"Kabin tabanı ile kat seviyesi hizalamasının doğru yapıldığı doğrulanmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Asansörün etiketinde belirtilen azami yük ve kişi sayısı kapasitesi kesinlikle aşılmamalıdır.\",\"Yük asansörlerinde malzeme kabin merkezine dengeli yüklenmeli ve devrilmeye karşı sabitlenmelidir.\",\"Otomatik kapıların kapanması el, ayak veya malzeme ile engellenmemelidir.\",\"Kabin hareket halindeyken zıplama veya kabin dengesini bozacak hareketlerden kaçınılmalıdır.\",\"Yük yükleme ve boşaltma esnasında kabin ile kat eşiği arasındaki boşluğa dikkat edilmelidir.\",\"Kabin içi acil stop butonu yalnızca tehlike ve acil durum anında kullanılmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Bakım ve onarım işlemleri yalnızca yetkili ve sertifikalı asansör bakım servisi tarafından yürütülmelidir.\",\"Bakım öncesinde EKED (Etiketleme-Kilitleme-Emniyete Alma-Denetleme) prosedürü uygulanarak ana güç kesilmelidir.\",\"Kuyu içi veya kabin üstü çalışmasında asansör kumandası REVİZYON moduna alınmalıdır.\",\"Tüm kat kapılarına \'BAKIM VAR - KULLANMAYINIZ\' uyarı levhaları ve emniyet şeritleri asılmalıdır.\",\"Bakım bitiminde tüm koruyucu kapaklar ve güvenlik devreleri tekrar aktif hale getirilmelidir.\",\"Makine dairesi ve kuyu dibi temizlenerek giriş kapıları kilitli tutulmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kırmızı etiketli (kullanımı tehlikeli) asansörlerin işletime alınması ve kullanılması kesinlikle yasaktır.\",\"Yangın, deprem ve afet anlarında asansörlerin tahliye amacıyla kullanılması yasaktır.\",\"İnsan asansörleriyle ağır ve dengesiz yük, yük asansörleriyle yetkisiz yolcu taşınması yasaktır.\",\"Asansör kuyu dibinde veya makine dairesinde atık ve malzeme depolanması yasaktır.\",\"Kat kapısı kilit mekanizmalarına dışarıdan yetkisiz müdahale yapılması yasaktır.\",\"Asansör kabini kat seviyesinde değilken kapı zorlanarak açılmaya çalışılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kabinde mahsur kalma durumunda sakin kalınmalı ve acil durum haberleşme butonuna basılarak yardım istenmelidir.\",\"Mahsur kalan kişileri kurtarma müdahalesi sadece eğitimli yetkili personel veya itfaiye tarafından yapılmalıdır.\",\"Yetkisiz kişilerin kapı kilit anahtarı kullanarak kurtarma yapmaya çalışması engellenmelidir.\",\"Anormal ses, sarsıntı veya durma hatası algılandığında asansör derhal durdurulup yetkililere haber verilmelidir.\",\"Arızalanan asansörün ana şalteri kapatılmalı ve üzerine arıza bilgi levhası asılmalıdır.\",\"Meydana gelen tüm arıza, kaza ve ramak kala olaylar derhal İSG birimine ve bina yönetimine bildirilmelidir.\"]}]', `updated_at` = NOW() WHERE `baslik` = 'ASANSÖR (İNSAN / YÜK) GÜVENLİ ÇALIŞMA TALİMATI' AND `aciklama` LIKE 'Yapay zek%';

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, buhar kazanının imalatçı talimatları ve ilgili standartlara (TS EN 12953) uygun şekilde güvenli kullanımını, periyodik kontrollerini, işletilmesini ve bakım aşamalarındaki iş sağlığı ve güvenliği kurallarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere dayanıklı koruyucu eldiven (EN 407 \\/ EN 388) kullanılmalıdır.\",\"Sıçramalara ve çapaklara karşı yan korumalı emniyet gözlüğü (EN 166) takılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş emniyet ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Yüksek gürültü seviyesine sahip alanlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Operatör yetkisi ve cihazın periyodik kontrol etiketinin geçerliliği kontrol edilmelidir.\",\"Su seviye göstergeleri, manometre ve emniyet valflerinin çalışırlığı kontrol edilmelidir.\",\"Besi suyu deposu su seviyesi ve yumuşatma sisteminin uygunluğu doğrulanmalıdır.\",\"Yakıt besleme hatları ve brülör bağlantılarında sızıntı kontrolü yapılmalıdır.\",\"Baca klapeleri, duman kanalları ve kazan dairesi havalandırma menfezleri açık tutulmalıdır.\",\"Emniyet blöfü ve otomatik seviye kontrol sistemlerinin testleri gerçekleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan işletme basıncı, kazan etiketinde ve imalatçı belgesinde belirtilen azami işletme basıncını aşmamalıdır.\",\"Su seviyesi çalışma boyunca takip edilmeli, emniyet alt sınırının altına düşmesine izin verilmemelidir.\",\"Emniyet valflerinin tutukluk yapmaması için vardiya başında manuel blöf kontrolü yapılmalıdır.\",\"Dip ve yüzey blöf işlemleri işletme talimatına uygun olarak aşamalı şekilde yapılmalıdır.\",\"Brülörün alev kontrolü ve yanma kalitesi izlenmeli, patlamalı ateşlemelere izin verilmemelidir.\",\"Kazan dairesi havalandırma fanları çalışma süresince kesintisiz devrede tutulmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kazan kapatıldıktan sonra ana besleme şalteri indirilerek EKED (Etiketleme-Kilitleme) uygulanmalıdır.\",\"Bakım öncesinde kazan iç basıncı tamamen sıfırlanmalı ve manometreden doğrulanmalıdır.\",\"Kazan soğumadan ve basınç tamamen düşmeden blöf vanaları ve gözetleme kilitleri açılmamalıdır.\",\"Yakıt ve gaz vanaları kapatılarak emniyet kilitleri takılmalı, hat emniyete alınmalıdır.\",\"Kazan içi temizlik ve denetim çalışmalarında 24 Volt alçak gerilim aydınlatması kullanılmalıdır.\",\"Yapılan tüm bakım, temizlik ve test verileri kazan işletme defterine eksiksiz kaydedilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan operatörlüğü belgesi (MYK \\/ MEB) bulunmayan kişilerin kazanı çalıştırması ve müdahale etmesi yasaktır.\",\"Basınç altındaki kazana, boru hatlarına veya vanalara kaynak ve darbeli müdahale yapılması yasaktır.\",\"Emniyet valflerinin ayarlarını değiştirmek, ağırlık eklemek veya valfleri körlemek yasaktır.\",\"Susuz kalmış aşırı ısınmış kazana aniden soğuk besi suyu basılması kesinlikle yasaktır.\",\"Kazan dairesi içinde yanıcı, parlayıcı malzeme depolanması ve açık alevle yaklaşılması yasaktır.\",\"Otomatik emniyet röleleri ve seviye denetleyicileri baypas edilerek kazan çalıştırılamaz.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın susuz kaldığı fark edildiğinde brülör derhal kapatılmalı, su verilmemeli ve sistem soğumaya bırakılmalıdır.\",\"Aşırı basınç yükselmesinde brülör acil stop butonuna basılarak yakıt akışı derhal kesilmelidir.\",\"Yakıt veya gaz kaçağı durumunda ana vanalar kapatılmalı, ortam havalandırılmalı ve şalterlere dokunulmamalıdır.\",\"Kazan dairesinde yangın çıkması halinde acil durum alarmı verilerek 112 Acil Çağrı Merkezi aranmalıdır.\",\"Tespit edilen her türlü arıza, anormal ses veya sızıntı derhal İSG Birimine ve İşletme Sorumlusuna bildirilmelidir.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Buhar Kazanı';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, buhar kazanının imalatçı talimatları ve ilgili standartlara (TS EN 12953) uygun şekilde güvenli kullanımını, periyodik kontrollerini, işletilmesini ve bakım aşamalarındaki iş sağlığı ve güvenliği kurallarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere dayanıklı koruyucu eldiven (EN 407 \\/ EN 388) kullanılmalıdır.\",\"Sıçramalara ve çapaklara karşı yan korumalı emniyet gözlüğü (EN 166) takılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş emniyet ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Yüksek gürültü seviyesine sahip alanlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Operatör yetkisi ve cihazın periyodik kontrol etiketinin geçerliliği kontrol edilmelidir.\",\"Su seviye göstergeleri, manometre ve emniyet valflerinin çalışırlığı kontrol edilmelidir.\",\"Besi suyu deposu su seviyesi ve yumuşatma sisteminin uygunluğu doğrulanmalıdır.\",\"Yakıt besleme hatları ve brülör bağlantılarında sızıntı kontrolü yapılmalıdır.\",\"Baca klapeleri, duman kanalları ve kazan dairesi havalandırma menfezleri açık tutulmalıdır.\",\"Emniyet blöfü ve otomatik seviye kontrol sistemlerinin testleri gerçekleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan işletme basıncı, kazan etiketinde ve imalatçı belgesinde belirtilen azami işletme basıncını aşmamalıdır.\",\"Su seviyesi çalışma boyunca takip edilmeli, emniyet alt sınırının altına düşmesine izin verilmemelidir.\",\"Emniyet valflerinin tutukluk yapmaması için vardiya başında manuel blöf kontrolü yapılmalıdır.\",\"Dip ve yüzey blöf işlemleri işletme talimatına uygun olarak aşamalı şekilde yapılmalıdır.\",\"Brülörün alev kontrolü ve yanma kalitesi izlenmeli, patlamalı ateşlemelere izin verilmemelidir.\",\"Kazan dairesi havalandırma fanları çalışma süresince kesintisiz devrede tutulmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kazan kapatıldıktan sonra ana besleme şalteri indirilerek EKED (Etiketleme-Kilitleme) uygulanmalıdır.\",\"Bakım öncesinde kazan iç basıncı tamamen sıfırlanmalı ve manometreden doğrulanmalıdır.\",\"Kazan soğumadan ve basınç tamamen düşmeden blöf vanaları ve gözetleme kilitleri açılmamalıdır.\",\"Yakıt ve gaz vanaları kapatılarak emniyet kilitleri takılmalı, hat emniyete alınmalıdır.\",\"Kazan içi temizlik ve denetim çalışmalarında 24 Volt alçak gerilim aydınlatması kullanılmalıdır.\",\"Yapılan tüm bakım, temizlik ve test verileri kazan işletme defterine eksiksiz kaydedilmelidir.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan operatörlüğü belgesi (MYK \\/ MEB) bulunmayan kişilerin kazanı çalıştırması ve müdahale etmesi yasaktır.\",\"Basınç altındaki kazana, boru hatlarına veya vanalara kaynak ve darbeli müdahale yapılması yasaktır.\",\"Emniyet valflerinin ayarlarını değiştirmek, ağırlık eklemek veya valfleri körlemek yasaktır.\",\"Susuz kalmış aşırı ısınmış kazana aniden soğuk besi suyu basılması kesinlikle yasaktır.\",\"Kazan dairesi içinde yanıcı, parlayıcı malzeme depolanması ve açık alevle yaklaşılması yasaktır.\",\"Otomatik emniyet röleleri ve seviye denetleyicileri baypas edilerek kazan çalıştırılamaz.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın susuz kaldığı fark edildiğinde brülör derhal kapatılmalı, su verilmemeli ve sistem soğumaya bırakılmalıdır.\",\"Aşırı basınç yükselmesinde brülör acil stop butonuna basılarak yakıt akışı derhal kesilmelidir.\",\"Yakıt veya gaz kaçağı durumunda ana vanalar kapatılmalı, ortam havalandırılmalı ve şalterlere dokunulmamalıdır.\",\"Kazan dairesinde yangın çıkması halinde acil durum alarmı verilerek 112 Acil Çağrı Merkezi aranmalıdır.\",\"Tespit edilen her türlü arıza, anormal ses veya sızıntı derhal İSG Birimine ve İşletme Sorumlusuna bildirilmelidir.\"]}]', `updated_at` = NOW() WHERE `baslik` = 'BUHAR KAZANI GÜVENLİ ÇALIŞMA TALİMATI' AND `aciklama` LIKE 'Yapay zek%';

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, sapan, zincir, çelik halat ve mapa gibi kaldırma aksesuarlarının TS EN 13414 ve TS EN 818 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu çerçevesinde güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını belirlemek amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere ve kesilmelere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Darbe ve ezilmelere karşı çelik burunlu emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Baş yaralanmalarını önlemek amacıyla endüstriyel baret (TS EN 397) takılmalıdır.\",\"Yüksekte yürütülen sapancı ve işaretçi çalışmalarında tam vücut emniyet kemeri (TS EN 361) kullanılmalıdır.\",\"Gözleri uçuşan parçacıklardan korumak için koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Saha çalışmasında yüksek görünürlük sağlamak için ikaz yeleği (TS EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma aksesuarının güvenli çalışma yükü (WLL) etiketi ve periyodik kontrol rengi kontrol edilmelidir.\",\"Çelik halat sapanlarda ezilme, kopuk tel, korozyon veya kuş yuvalanması deformasyonu incelenmelidir.\",\"Zincir sapan baklalarında aşınma, çatlak, uzama veya TS EN 818 standart dışı deformasyon kontrol edilmelidir.\",\"Mapaların pimi, diş yapısı ve emniyet kopilyasının eksiksiz ve uygun boyutta olduğu doğrulanmalıdır.\",\"Bez ve dokuma sapanlarda lif kopması, kesik, yanık veya kimyasal yıpranma kontrol edilmelidir.\",\"Kaldırılacak yükün ağırlığı ve ağırlık merkezi belirlenerek uygun açı ve kapasitede aksesuar seçilmelidir.\",\"Keskin kenarlı yüklerde sapanların zedelenmesini önlemek için uygun köşe koruyucu aparatlar yerleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sapan açıları dikkate alınmalı, sapan kolları arasındaki tepe açısı 120 dereceyi kesinlikle geçmemelidir.\",\"Kancaya takılan sapan halkalarının emniyet mandalını tam kapatacak şekilde oturduğu doğrulanmalıdır.\",\"Mapalar tam torkunda sıkılmalı ve eksenel olmayan yan yüklemelere maruz bırakılmamalıdır.\",\"Yük kaldırılırken sapan gerginliği kademeli olarak artırılmalı, ani kaldırma ve boşlama yapılmamalıdır.\",\"Yükün salınımını önlemek için kılavuz halatı kullanılmalı, yüke doğrudan elle müdahale edilmemelidir.\",\"Kaldırma esnasında aksesuarların birbiri üstüne biniş yapması veya burulması önlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kullanım sonrası sapanlar, zincirler ve mapalar kir, yağ ve nemden arındırılarak temizlenmelidir.\",\"Aksesuarlar doğrudan güneş ışığı almayan, kuru ve korumalı alanlardaki özel askılıklarda muhafaza edilmelidir.\",\"Hasarlı, etiket bilgisi okunaksız veya standart dışı tespit edilen aksesuarlar derhal kullanımdan çekilmelidir.\",\"Kullanım dışı bırakılan aksesuarlara \'KULLANIMI TEHLİKELİDİR\' etiketi takılmalı ve yanlışlıkla kullanılmaması için ayrı (karantina) bölgede tutulmalıdır.\",\"Çelik halat ve zincir aksesuarlar imalatçı talimatlarına uygun olarak periyodik yağlama işlemine tabi tutulmalıdır.\",\"Aksesuarların periyodik kontrolleri, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği\'nde belirtilen sürelerde yetkili kişilere yaptırılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Güvenli çalışma yükü (WLL) etiketi bulunmayan veya okunamayan aksesuarları kullanmak yasaktır.\",\"Kopuk tel sayısı sınırını aşmış çelik halatları ve baklalarında uzama olan zincirleri kullanmak yasaktır.\",\"Sapanlara düğüm atmak, cıvata ile zincir boyu kısaltmak veya kaynaklı tamirat yapmak yasaktır.\",\"Hasarlı, dişleri bozulmuş veya pimi orijinal olmayan mapaları kullanmak yasaktır.\",\"Sapan kolları arasında 120 dereceden fazla açı oluşturacak şekilde kaldırma yapmak yasaktır.\",\"Keskin kenarlı yüklere koruyucu ped veya aparat takmadan sapan bağlamak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aksesuar kayması veya deformasyon riski görüldüğünde çalışma derhal durdurulmalıdır.\",\"Tehlikeli durum ve aksesuar arızaları vakit kaybetmeksizin birim amirine ve İSG birimine bildirilmelidir.\",\"Yük düşmesi veya devrilmesi durumunda alan derhal emniyet şeridine alınarak erişim kısıtlanmalıdır.\",\"Yaralanmalı kazalarda ilk yardım müdahalesi yapılarak 112 Acil Çağrı Merkezi bilgilendirilmelidir.\",\"Kazaya veya tehlikeye neden olan aksesuar ve olay yeri inceleme tamamlanana kadar korunmalıdır.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Kaldırma Aksesuarları (sapan, zincir, halat, mapa)';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, sapan, zincir, çelik halat ve mapa gibi kaldırma aksesuarlarının TS EN 13414 ve TS EN 818 standartları ile 6331 sayılı İş Sağlığı ve Güvenliği Kanunu çerçevesinde güvenli kullanımını, periyodik kontrollerini ve bakım esaslarını belirlemek amacıyla hazırlanmıştır.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Mekanik risklere ve kesilmelere karşı koruyucu iş eldiveni (TS EN 388) kullanılmalıdır.\",\"Darbe ve ezilmelere karşı çelik burunlu emniyet ayakkabısı (TS EN ISO 20345) giyilmelidir.\",\"Baş yaralanmalarını önlemek amacıyla endüstriyel baret (TS EN 397) takılmalıdır.\",\"Yüksekte yürütülen sapancı ve işaretçi çalışmalarında tam vücut emniyet kemeri (TS EN 361) kullanılmalıdır.\",\"Gözleri uçuşan parçacıklardan korumak için koruyucu gözlük (TS EN 166) takılmalıdır.\",\"Saha çalışmasında yüksek görünürlük sağlamak için ikaz yeleği (TS EN ISO 20471) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kaldırma aksesuarının güvenli çalışma yükü (WLL) etiketi ve periyodik kontrol rengi kontrol edilmelidir.\",\"Çelik halat sapanlarda ezilme, kopuk tel, korozyon veya kuş yuvalanması deformasyonu incelenmelidir.\",\"Zincir sapan baklalarında aşınma, çatlak, uzama veya TS EN 818 standart dışı deformasyon kontrol edilmelidir.\",\"Mapaların pimi, diş yapısı ve emniyet kopilyasının eksiksiz ve uygun boyutta olduğu doğrulanmalıdır.\",\"Bez ve dokuma sapanlarda lif kopması, kesik, yanık veya kimyasal yıpranma kontrol edilmelidir.\",\"Kaldırılacak yükün ağırlığı ve ağırlık merkezi belirlenerek uygun açı ve kapasitede aksesuar seçilmelidir.\",\"Keskin kenarlı yüklerde sapanların zedelenmesini önlemek için uygun köşe koruyucu aparatlar yerleştirilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Sapan açıları dikkate alınmalı, sapan kolları arasındaki tepe açısı 120 dereceyi kesinlikle geçmemelidir.\",\"Kancaya takılan sapan halkalarının emniyet mandalını tam kapatacak şekilde oturduğu doğrulanmalıdır.\",\"Mapalar tam torkunda sıkılmalı ve eksenel olmayan yan yüklemelere maruz bırakılmamalıdır.\",\"Yük kaldırılırken sapan gerginliği kademeli olarak artırılmalı, ani kaldırma ve boşlama yapılmamalıdır.\",\"Yükün salınımını önlemek için kılavuz halatı kullanılmalı, yüke doğrudan elle müdahale edilmemelidir.\",\"Kaldırma esnasında aksesuarların birbiri üstüne biniş yapması veya burulması önlenmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kullanım sonrası sapanlar, zincirler ve mapalar kir, yağ ve nemden arındırılarak temizlenmelidir.\",\"Aksesuarlar doğrudan güneş ışığı almayan, kuru ve korumalı alanlardaki özel askılıklarda muhafaza edilmelidir.\",\"Hasarlı, etiket bilgisi okunaksız veya standart dışı tespit edilen aksesuarlar derhal kullanımdan çekilmelidir.\",\"Kullanım dışı bırakılan aksesuarlara \'KULLANIMI TEHLİKELİDİR\' etiketi takılmalı ve yanlışlıkla kullanılmaması için ayrı (karantina) bölgede tutulmalıdır.\",\"Çelik halat ve zincir aksesuarlar imalatçı talimatlarına uygun olarak periyodik yağlama işlemine tabi tutulmalıdır.\",\"Aksesuarların periyodik kontrolleri, İş Ekipmanlarının Kullanımında Sağlık ve Güvenlik Şartları Yönetmeliği\'nde belirtilen sürelerde yetkili kişilere yaptırılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Güvenli çalışma yükü (WLL) etiketi bulunmayan veya okunamayan aksesuarları kullanmak yasaktır.\",\"Kopuk tel sayısı sınırını aşmış çelik halatları ve baklalarında uzama olan zincirleri kullanmak yasaktır.\",\"Sapanlara düğüm atmak, cıvata ile zincir boyu kısaltmak veya kaynaklı tamirat yapmak yasaktır.\",\"Hasarlı, dişleri bozulmuş veya pimi orijinal olmayan mapaları kullanmak yasaktır.\",\"Sapan kolları arasında 120 dereceden fazla açı oluşturacak şekilde kaldırma yapmak yasaktır.\",\"Keskin kenarlı yüklere koruyucu ped veya aparat takmadan sapan bağlamak yasaktır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aksesuar kayması veya deformasyon riski görüldüğünde çalışma derhal durdurulmalıdır.\",\"Tehlikeli durum ve aksesuar arızaları vakit kaybetmeksizin birim amirine ve İSG birimine bildirilmelidir.\",\"Yük düşmesi veya devrilmesi durumunda alan derhal emniyet şeridine alınarak erişim kısıtlanmalıdır.\",\"Yaralanmalı kazalarda ilk yardım müdahalesi yapılarak 112 Acil Çağrı Merkezi bilgilendirilmelidir.\",\"Kazaya veya tehlikeye neden olan aksesuar ve olay yeri inceleme tamamlanana kadar korunmalıdır.\"]}]', `updated_at` = NOW() WHERE `baslik` = 'KALDIRMA AKSESUARLARI (SAPAN, ZİNCİR, HALAT, MAPA) GÜVENLİ ÇALIŞMA TALİMATI' AND `aciklama` LIKE 'Yapay zek%';

UPDATE `talimat_sablonlari` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, kalorifer ve sıcak su kazanlarının güvenli şekilde işletilmesi, periyodik bakımı ve olası iş kazaları ile meslek hastalıklarının önlenmesine yönelik uygulama esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere karşı koruyucu iş eldiveni (EN 388, EN 407) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş güvenliği ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Çapak ve sıvı sıçramalarına karşı koruyucu iş gözlüğü (EN 166) takılmalıdır.\",\"Gürültü seviyesinin 85 dB(A) değerini aştığı durumlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Temizlik, kül alma veya yakıt yükleme işlerinde parçacık filtreli toz maskesi (EN 149 FFP2) takılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın yıllık periyodik kontrol etiketinin güncel olduğu teyit edilmelidir.\",\"Su seviye göstergeleri, manometreler ve emniyet ventillerinin çalışırlığı denetlenmelidir.\",\"Kazan dairesinin tabii ve cebri havalandırma sistemlerinin açık olduğu kontrol edilmelidir.\",\"Yakıt hatlarında, vanalarda ve brülör bağlantılarında gaz veya yakıt kaçağı denetimi yapılmalıdır.\",\"Genleşme tankı ön basıncı ve tesisattaki su miktarı uygun seviyede olmalıdır.\",\"Kazan dairesinde yanıcı, patlayıcı ve yabancı maddelerin bulunmadığından emin olunmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan çalışma basıncı ve su sıcaklığı manometre ile termometreden sürekli takip edilmelidir.\",\"Alev gözetleme camından brülörün yanma durumu ve alev boyu düzenli olarak izlenmelidir.\",\"Su seviyesi emniyet sınırının altına düştüğünde brülör otomatik olarak durmalı, durmazsa elle müdahale edilmelidir.\",\"Sıcak yüzeylerle teması önlemek için yalıtımsız hatlara ve kazan gövdesine koruyucusuz dokunulmamalıdır.\",\"Çalışma esnasında kazan dairesi kapıları kilitlenmemeli ve kaçış yolları açık tutulmalıdır.\",\"Emniyet ventillerinin manuel tahliye kolları aşırı basınç oluşmadan dönemsel olarak test edilmelidir.\"]},{\"baslik\":\"ÇALIŞMA SONRASI VE BAKIM\",\"aciklama\":\"\",\"maddeler\":[\"Kazan kapatılacağında öncelikle brülör durdurulmalı, kazan sıcaklığı güvenli seviyeye düşene kadar sirkülasyon pompaları çalıştırılmalıdır.\",\"Bakım ve onarım işlemlerinden önce elektrik beslemesi kesilmeli ve Etiketleme-Kilitleme (EKED\\/LOTO) uygulanmalıdır.\",\"Kazan içi basınç tamamen sıfırlanmadan ve su sıcaklığı düşmeden blöf ve boşaltma vanaları açılmamalıdır.\",\"Kazan gövde içi veya baca temizliği yapılmadan önce sistem havalandırılmalı ve gaz birikimi olmadığından emin olunmalıdır.\",\"Dip blöf işlemi basınç düşük seviyedeyken ve kademeli olarak gerçekleştirilmelidir.\",\"Periyodik bakımlar yetkili servisler ve uzman personeller tarafından kaydedilerek yapılmalıdır.\"]},{\"baslik\":\"YASAKLAR\",\"aciklama\":\"\",\"maddeler\":[\"Susuz kalan veya aşırı ısınan kazana kesinlikle ani soğuk su beslemesi yapılmamalıdır.\",\"Emniyet valflerinin ve basınç otomatiğinin ayarları yetkisiz kişilerce değiştirilmemeli veya kilitlenmemelidir.\",\"Kazan dairesinde sigara içilmemeli, açık ateş yakılmamalı ve kıvılcım çıkaran aletler kullanılmamalıdır.\",\"Kazan dairesi depo, ardiye veya soyunma odası gibi amaç dışı kullanılmamalıdır.\",\"Kalorifer ateşçisi belgesi bulunmayan ve yetkisiz kişilerin kazanı çalıştırmasına ve kazan dairesinde müdahalede bulunmasına izin verilmemelidir.\",\"Basınç altındaki hatlarda veya gövdede kaynak, sıkma ve mekanik müdahale yapılmamalıdır.\"]},{\"baslik\":\"ACİL DURUM VE ARIZA BİLDİRİMİ\",\"aciklama\":\"\",\"maddeler\":[\"Aşırı basınç artışı veya anormal ses duyulduğunda acil stop butonuna basılarak brülör derhal kapatılmalıdır.\",\"Gaz kokusu veya sızıntısı hissedildiğinde ana gaz vanası kapatılmalı, elektrik anahtarlarına dokunulmadan ortam havalandırılmalıdır.\",\"Yangın durumunda ilk olarak ana yakıt ve elektrik besleme vanaları\\/şalterleri kapatılmalıdır.\",\"Her türlü arıza, su kaçağı ve emniyet bileşeni arızası derhal İş Güvenliği Uzmanı ve Teknik Bakım Sorumlusuna bildirilmelidir.\",\"Acil durum müdahalesi sonrasında yetkili teknik personel onay vermeden cihaz yeniden işletime alınmamalıdır.\"]}]', `updated_at` = NOW() WHERE `ekipman_tipi` = 'Kalorifer Kazanı / Sıcak Su Kazanı';
UPDATE `talimatlar` SET `bolumler` = '[{\"baslik\":\"AMAÇ VE KAPSAM\",\"aciklama\":\"Bu talimat, kalorifer ve sıcak su kazanlarının güvenli şekilde işletilmesi, periyodik bakımı ve olası iş kazaları ile meslek hastalıklarının önlenmesine yönelik uygulama esaslarını kapsar.\",\"maddeler\":[]},{\"baslik\":\"KİŞİSEL KORUYUCU DONANIMLAR (KKD)\",\"aciklama\":\"\",\"maddeler\":[\"Isıya ve mekanik risklere karşı koruyucu iş eldiveni (EN 388, EN 407) kullanılmalıdır.\",\"Çelik burunlu ve kaymaz tabanlı iş güvenliği ayakkabısı (EN ISO 20345) giyilmelidir.\",\"Çapak ve sıvı sıçramalarına karşı koruyucu iş gözlüğü (EN 166) takılmalıdır.\",\"Gürültü seviyesinin 85 dB(A) değerini aştığı durumlarda kulak koruyucu (EN 352-2) kullanılmalıdır.\",\"Temizlik, kül alma veya yakıt yükleme işlerinde parçacık filtreli toz maskesi (EN 149 FFP2) takılmalıdır.\",\"Isıya ve aleve dayanıklı koruyucu iş elbisesi (EN ISO 11612) giyilmelidir.\"]},{\"baslik\":\"ÇALIŞMA ÖNCESİ ALINACAK GÜVENLİK ÖNLEMLERİ\",\"aciklama\":\"\",\"maddeler\":[\"Kazanın yıllık periyodik kontrol etiketinin güncel olduğu teyit edilmelidir.\",\"Su seviye göstergeleri, manometreler ve emniyet ventillerinin çalışırlığı denetlenmelidir.\",\"Kazan dairesinin tabii ve cebri havalandırma sistemlerinin açık olduğu kontrol edilmelidir.\",\"Yakıt hatlarında, vanalarda ve brülör bağlantılarında gaz veya yakıt kaçağı denetimi yapılmalıdır.\",\"Genleşme tankı ön basıncı ve tesisattaki su miktarı uygun seviyede olmalıdır.\",\"Kazan dairesinde yanıcı, patlayıcı ve yabancı maddelerin bulunmadığından emin olunmalıdır.\"]},{\"baslik\":\"ÇALIŞMA SIRASINDA UYULACAK KURALLAR\",\"aciklama\":\"\",\"maddeler\":[\"Kazan çalışma basıncı ve su sıcaklığı manometre ile termometreden sürekli takip edilmelidir.\",\"Alev gözetleme camından brülörün yanma durumu ve alev boyu düzenli olarak izlenmelidir.\",\"Su seviyesi emniyet sınırının altına düştüğünde brülör otomatik olarak durmalı, durmazsa elle müdahale edilmelidir.\",\"Sıcak yüzeylerle teması önleme